# Generated by manage.py generate_test_cases.
from unittest.mock import patch
from dataclasses import replace
from django.http import HttpResponse
from bloomerp.communication.builtins.instant_messaging.registry import (
    IM_PROVIDER_REGISTRY,
)
from bloomerp.communication.builtins.instant_messaging.builtins.bloomerp import (
    INTERNAL_IM_PROVIDER,
)

from django.contrib.auth import get_user_model

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


from .phone_fixtures import PhoneDirectoryFixtures


class TestRecipientsComponent(PhoneDirectoryFixtures, BloomerpComponentTestCase):
    """Verify active staff can discover each other without user-model permissions."""

    view_name = "components_im_recipients"

    def prepare_excluded_users(self, scenario: RequestScenario) -> None:
        """Add inactive staff and non-staff accounts that must stay out of search."""
        user_model = get_user_model()
        user_model.objects.create(
            username="inactive_staff", is_staff=True, is_active=False
        )
        user_model.objects.create(username="non_staff", is_staff=False)

    def prepare_non_staff_actor(self, scenario: RequestScenario) -> None:
        """Authenticate a non-staff user without granting directory access."""
        scenario.user = get_user_model().objects.create(username="non_staff_actor")

    def prepare_email_directory(self, scenario: RequestScenario) -> None:
        """Use email login and search a recipient whose username does not match."""
        self.enterContext(patch.object(get_user_model(), "USERNAME_FIELD", "email"))
        self.normal_user.email = "directory-recipient@example.test"
        self.normal_user.save(update_fields=["email"])

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover staff eligibility, policy-independent search, validation and login."""
        scenarios = [
            RequestScenario(
                name="Readable phone field uses object string label",
                user=self.normal_user,
                prepare=self.phone_setup,
                query_params={"recipient_query": "Phone directory contact"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Phone directory contact"),
                        self.contains_text("+32470000003"),
                    ]
                ),
            ),
            RequestScenario(
                name="Staff directory without an internal connection",
                user=self.admin_user,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("johndoe"),
                        self.contains_text("recipient_id"),
                    ]
                ),
            ),
            RequestScenario(
                name="Staff without policies can discover other staff",
                user=self.normal_user,
                prepare=self.prepare_excluded_users,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('value="' + str(self.admin_user.pk) + '"'),
                        self.does_not_contain_text(
                            'value="' + str(self.normal_user.pk) + '"'
                        ),
                        self.does_not_contain_text("inactive_staff"),
                        self.does_not_contain_text("non_staff"),
                    ]
                ),
            ),
            RequestScenario(
                name="Non-staff cannot discover recipients",
                prepare=self.prepare_non_staff_actor,
                expected=ExpectedResult(
                    response_validators=[self.does_not_contain_text("recipient_id")]
                ),
            ),
            RequestScenario(
                name="Search filters recipient names",
                user=self.admin_user,
                query_params={"recipient_query": "unmatched"},
                expected=ExpectedResult(
                    response_validators=[self.does_not_contain_text("recipient_id")]
                ),
            ),
            RequestScenario(
                name="Reject malformed cursor",
                user=self.admin_user,
                query_params={"cursor": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Anonymous login required",
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Directory searches the configured email login field",
                user=self.admin_user,
                prepare=self.prepare_email_directory,
                query_params={"recipient_query": "directory-recipient"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('value="' + str(self.normal_user.pk) + '"'),
                    ]
                ),
            ),
        ]

        scenarios.extend(
            [
                RequestScenario(
                    name="Group creation belongs to the Bloomerp provider section",
                    user=self.admin_user,
                    expected=ExpectedResult(
                        response_validators=[self.validate_provider_placement]
                    ),
                ),
                RequestScenario(
                    name="Filtered phone directory has no group creation",
                    user=self.admin_user,
                    query_params={"provider": "phone"},
                    expected=ExpectedResult(
                        response_validators=[self.does_not_contain_text("create_group")]
                    ),
                ),
                RequestScenario(
                    name="Non-staff see no group creation action",
                    prepare=self.prepare_non_staff_actor,
                    expected=ExpectedResult(
                        response_validators=[self.does_not_contain_text("create_group")]
                    ),
                ),
                RequestScenario(
                    name="Creation-only provider renders its own declared action",
                    user=self.admin_user,
                    prepare=self.prepare_alternate_creation,
                    query_params={"provider": "example"},
                    expected=ExpectedResult(
                        response_validators=[
                            self.contains_text("Example creation"),
                            self.contains_text("provider=example"),
                            self.contains_text("action=example_action"),
                            self.does_not_contain_text("provider=internal"),
                        ]
                    ),
                ),
            ]
        )
        return scenarios

    def validate_provider_placement(self, response: HttpResponse) -> bool:
        """Ensure the group shortcut appears inside Bloomerp and no other provider declares it."""
        html = response.content.decode()
        section = html.split('data-im-provider="internal"', 1)[1].split(
            "data-im-provider=", 1
        )[0]
        return "im-internal-create_group" in section and all(
            not group["actions"]
            for group in response.context["groups"]
            if group["provider"].key != "internal"
        )

    def prepare_alternate_creation(self, scenario: RequestScenario) -> None:
        """Expose a definition-owned action on a provider with no recipient selection steps."""
        action = replace(
            INTERNAL_IM_PROVIDER.creation_actions[0],
            key="example_action",
            label="Example creation",
        )
        provider = replace(
            INTERNAL_IM_PROVIDER,
            key="example",
            display_name="Example provider",
            selection_steps=(),
            creation_actions=(action,),
        )
        self.enterContext(
            patch.dict(IM_PROVIDER_REGISTRY._registry, {"example": provider})
        )
